-- AI-assisted Candidate Review documents, scoped per company.
--
-- Three pieces of state:
--   1. jobs.role_rubric            - optional weighted criteria a hiring
--                                    manager wants every candidate scored
--                                    against. Edited by recruiters; if
--                                    null the AI infers from the job
--                                    description.
--   2. candidate_job_review        - the live, mutable analysis for one
--                                    (candidate, job) pair. Generated by
--                                    AI on demand, then editable by
--                                    recruiters. The Live Review page on
--                                    a company aggregates rows here for
--                                    every candidate matched to any of
--                                    that company's active jobs.
--   3. candidate_review_snapshot   - an immutable frozen-in-time JSON
--                                    payload of an entire company's
--                                    review document. The /reviews
--                                    library lists these. Once taken,
--                                    snapshots are never mutated - they
--                                    are the citable record.
--
-- Idempotent: safe to re-run.

-- =====================================================================
-- 1. Per-job rubric
--
-- Shape: [{ "criterion": "Cybersecurity knowledge", "weight": 3 }, …]
-- Weight 1-5. AI uses it (with weights) to compute role_fit_score on
-- each review row. Falls back to inferring from description if null.
-- =====================================================================
alter table public.jobs
  add column if not exists role_rubric jsonb;

-- =====================================================================
-- 2. Live per-(candidate, job) review
-- =====================================================================
create table if not exists public.candidate_job_review (
  id                    uuid primary key default gen_random_uuid(),
  candidate_id          uuid not null
                        references public.candidates(id) on delete cascade,
  job_id                uuid not null
                        references public.jobs(id) on delete cascade,

  -- Structured review fields. Match the review PDF layout so the
  -- live page renders the same shape.
  background_summary    text,
  strengths             text[]   not null default '{}',
  areas_to_validate     text[]   not null default '{}',
  interview_focus       text[]   not null default '{}',

  -- Overall role-fit score, 0..3, used to render the green-dot bar.
  role_fit_score        numeric(3, 2),

  -- Per-criterion subscores so the rubric editor and the document body
  -- can break out the rating. Shape:
  --   [{ "criterion": "Cybersecurity knowledge", "score": 3, "weight": 3 }, …]
  rubric_scores         jsonb,

  -- Provenance - every regenerate stamps these. Edits stamp edited_*.
  ai_model              text,
  ai_generated_at       timestamptz,
  edited_at             timestamptz,
  edited_by             uuid references public.employees(id) on delete set null,

  -- 'pending-resume' when the candidate has no usable resume_url yet;
  -- 'ready' once an AI pass has run; 'manual' once a recruiter has
  -- saved an override.
  state                 text not null default 'pending-resume'
                          check (state in ('pending-resume','ready','manual')),

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  unique (candidate_id, job_id)
);

create index if not exists candidate_job_review_job_idx
  on public.candidate_job_review(job_id);
create index if not exists candidate_job_review_candidate_idx
  on public.candidate_job_review(candidate_id);

drop trigger if exists set_updated_at on public.candidate_job_review;
create trigger set_updated_at
  before update on public.candidate_job_review
  for each row execute function public.set_updated_at();

-- =====================================================================
-- 3. Immutable company-level snapshots
--
-- payload shape (intentionally denormalised so the snapshot stands
-- alone even if the source rows later change or get deleted):
--   {
--     "company": { "id":..., "company_name":..., ... },
--     "jobs": [ { "id":..., "title":..., "rubric": [...] }, … ],
--     "candidates": [
--       { "id":..., "first_name":..., "last_name":..., "location":...,
--         "reviews": [
--           { "job_id":..., "background_summary":..., "strengths": [...],
--             "areas_to_validate": [...], "interview_focus": [...],
--             "role_fit_score": 2.5, "rubric_scores": [...] }, …
--         ]
--       }, …
--     ],
--     "rankings": { "<job_id>": [ "<candidate_id>", … ], … },
--     "ai_model": "gpt-4o-mini",
--   }
-- =====================================================================
create table if not exists public.candidate_review_snapshot (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  label           text,
  payload         jsonb not null,
  ai_model        text,
  taken_by        uuid references public.employees(id) on delete set null,
  created_at      timestamptz not null default now()
);

create index if not exists candidate_review_snapshot_company_idx
  on public.candidate_review_snapshot(company_id, created_at desc);

-- =====================================================================
-- 4. RLS - same gates as the rest of the CRM.
-- =====================================================================
alter table public.candidate_job_review        enable row level security;
alter table public.candidate_review_snapshot   enable row level security;

drop policy if exists "candidate_job_review read"   on public.candidate_job_review;
drop policy if exists "candidate_job_review insert" on public.candidate_job_review;
drop policy if exists "candidate_job_review update" on public.candidate_job_review;
drop policy if exists "candidate_job_review delete" on public.candidate_job_review;
drop policy if exists "candidate_review_snapshot read"   on public.candidate_review_snapshot;
drop policy if exists "candidate_review_snapshot insert" on public.candidate_review_snapshot;
drop policy if exists "candidate_review_snapshot delete" on public.candidate_review_snapshot;

create policy "candidate_job_review read"
  on public.candidate_job_review for select
  to authenticated
  using (public.is_active_employee());

create policy "candidate_job_review insert"
  on public.candidate_job_review for insert
  to authenticated
  with check (
    public.is_active_employee()
    and public.current_employee_role() in ('Admin', 'Recruiter')
  );

create policy "candidate_job_review update"
  on public.candidate_job_review for update
  to authenticated
  using (
    public.is_active_employee()
    and public.current_employee_role() in ('Admin', 'Recruiter')
  )
  with check (
    public.is_active_employee()
    and public.current_employee_role() in ('Admin', 'Recruiter')
  );

create policy "candidate_job_review delete"
  on public.candidate_job_review for delete
  to authenticated
  using (
    public.is_active_employee()
    and public.current_employee_role() = 'Admin'
  );

create policy "candidate_review_snapshot read"
  on public.candidate_review_snapshot for select
  to authenticated
  using (public.is_active_employee());

create policy "candidate_review_snapshot insert"
  on public.candidate_review_snapshot for insert
  to authenticated
  with check (
    public.is_active_employee()
    and public.current_employee_role() in ('Admin', 'Recruiter')
  );

-- Snapshots are immutable for everyone (they exist as the citable
-- historical record). Even Admin can delete one, but no UPDATE policy
-- is defined so no role can mutate the payload.
create policy "candidate_review_snapshot delete"
  on public.candidate_review_snapshot for delete
  to authenticated
  using (
    public.is_active_employee()
    and public.current_employee_role() = 'Admin'
  );
